public static class L {
 public static bool Applying;
 static readonly Dictionary<string,string> Words=Create();
 static readonly KeyValuePair<string,string>[] Ordered=Words.OrderByDescending(x=>x.Key.Length).ToArray();
 class Record {public string Source,Last,Access,LastAccess;public List<string> Items;}
 static readonly ConditionalWeakTable<object,Record> Records=new ConditionalWeakTable<object,Record>();
 public static bool English {get{return Preferences.Current.Language=="en";}}
 public static void ApplyCulture(){var culture=CultureInfo.GetCultureInfo(English?"en-US":"ru-RU");Thread.CurrentThread.CurrentCulture=culture;Thread.CurrentThread.CurrentUICulture=culture;}
 public static string T(string value){if(!English||String.IsNullOrEmpty(value))return value;string exact;if(Words.TryGetValue(value,out exact))return exact;if(!value.Any(c=>c>='\u0400'&&c<='\u04ff'))return value;foreach(var item in Ordered)value=value.Replace(item.Key,item.Value);return value;}
 static string Source(string value){if(String.IsNullOrEmpty(value)||value.Any(c=>c>='\u0400'&&c<='\u04ff'))return value;foreach(var item in Ordered.OrderByDescending(x=>x.Value.Length))if(item.Value.Length>3)value=value.Replace(item.Value,item.Key);return value;}
 public static void Localize(Control root){bool previous=Applying;Applying=true;try{Walk(root);}finally{Applying=previous;}}
 static void Walk(Control c){var record=Records.GetValue(c,delegate(object key){return new Record();});if(!(c is TextBoxBase)&&!(c is NumericUpDown)){if(record.Source==null||c.Text!=record.Last)record.Source=Source(c.Text);c.Text=T(record.Source);record.Last=c.Text;}
  if(!String.IsNullOrEmpty(c.AccessibleName)){if(record.Access==null||c.AccessibleName!=record.LastAccess)record.Access=Source(c.AccessibleName);c.AccessibleName=T(record.Access);record.LastAccess=c.AccessibleName;}
  var combo=c as ComboBox;if(combo!=null){if(record.Items==null||record.Items.Count!=combo.Items.Count)record.Items=combo.Items.Cast<object>().Select(x=>Source(x.ToString())).ToList();int selected=combo.SelectedIndex;combo.BeginUpdate();for(int i=0;i<combo.Items.Count;i++){string next=T(record.Items[i]);if(combo.Items[i] is string&&combo.Items[i].ToString()!=next)combo.Items[i]=next;}combo.SelectedIndex=selected;combo.EndUpdate();}
  if(c.ContextMenuStrip!=null)foreach(ToolStripItem item in c.ContextMenuStrip.Items)LocalizeItem(item);foreach(Control child in c.Controls)Walk(child);
 }
 static void LocalizeItem(ToolStripItem item){var record=Records.GetValue(item,delegate(object key){return new Record();});if(record.Source==null||item.Text!=record.Last)record.Source=Source(item.Text);item.Text=T(record.Source);record.Last=item.Text;var menu=item as ToolStripMenuItem;if(menu!=null)foreach(ToolStripItem child in menu.DropDownItems)LocalizeItem(child);}
 public static void Tooltips(ToolTip tip,Control root){string text=tip.GetToolTip(root);if(!String.IsNullOrEmpty(text))tip.SetToolTip(root,T(Source(text)));foreach(Control c in root.Controls)Tooltips(tip,c);}
